{"name":"typec_partner_deattach","qualified_name":"workspace-linux.drivers.usb.typec.class.typec_partner_deattach","label":"Function","file_path":"/workspace/linux/drivers/usb/typec/class.c","start_line":2169,"end_line":2186,"source":"static void typec_partner_deattach(struct typec_connector *con, struct device *dev)
{
	struct typec_port *port = container_of(con, struct typec_port, con);
	struct typec_partner *partner;

	mutex_lock(&port->partner_link_lock);
	partner = typec_get_partner(port);
	if (partner) {
		typec_partner_unlink_device(partner, dev);
		put_device(&partner->dev);
	}

	if (port->usb2_dev == dev)
		port->usb2_dev = NULL;
	else if (port->usb3_dev == dev)
		port->usb3_dev = NULL;
	mutex_unlock(&port->partner_link_lock);
}
